  Process.demonitor(ref, [:flush])

  case result do
    {:ok, _deleted_count} -> finish_sweep_cycle(state)
    {:error, %ErrorMessage{}} -> finish_sweep_cycle(state)
  end
end

def finish_sweep(%State{} = state, _stale_ref, _result), do: state

