    %State{state | sweep_task: task, sweep_pending?: false}
  rescue
    RuntimeError -> %State{state | sweep_task: nil, sweep_pending?: false}
  catch
    :exit, _reason -> %State{state | sweep_task: nil, sweep_pending?: false}
  end
